def count_names(text):
    counts = {}
    for part in text.split(","):
        name = part.strip()
        if not name:
            continue
        counts[name] = counts.get(name, 0) + 1
    return counts

counts = count_names(input())
if not counts:
    print("이름 없음")
for name, count in counts.items():
    print(name, count)

