class Credit:
    def __init__(self, amount):
        self.remaining = amount

    def use(self, cost):
        if cost < 0 or cost > self.remaining:
            return False
        self.remaining = self.remaining - cost
        return True

def main():
    credit = Credit(5)
    for part in input().split():
        try:
            cost = int(part)
        except ValueError:
            print("숫자 아님:", part)
            continue
        if credit.use(cost):
            print("사용:", cost)
        else:
            print("거절:", cost)
    print("잔여:", credit.remaining)

if __name__ == "__main__":
    main()

